import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"10. Quality Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/10-quality-requirements.md","filePath":"architecture/arc42/10-quality-requirements.md","lastUpdated":1780254295000}'),l={name:"architecture/arc42/10-quality-requirements.md"};function n(o,e,s,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_10-quality-requirements" tabindex="-1">10. Quality Requirements <a class="header-anchor" href="#_10-quality-requirements" aria-label="Permalink to &quot;10. Quality Requirements&quot;">​</a></h1><p>This section lists concrete “quality scenarios” that guide design and testing.</p><h2 id="availability-and-offline" tabindex="-1">Availability and offline <a class="header-anchor" href="#availability-and-offline" aria-label="Permalink to &quot;Availability and offline&quot;">​</a></h2><ul><li>A workspace can operate on LAN with no internet: peers discover via mDNS and sync directly.</li><li>When the internet is available, peers can discover/dial via rendezvous and fall back to relays.</li><li>Always-on bots (VDF role) can improve availability by caching frequently needed content.</li></ul><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>A remote, untrusted peer cannot gain membership without a valid signed capability.</li><li>A cache-only peer cannot become a source of truth for user uploads (no upload endpoints; cache fills only via fetch-by-CID).</li><li>A peer never persists/serves blob bytes that do not match the requested CID.</li></ul><h2 id="operability" tabindex="-1">Operability <a class="header-anchor" href="#operability" aria-label="Permalink to &quot;Operability&quot;">​</a></h2><ul><li>Server daemons expose <code>GET /healthz</code> and <code>GET /metrics</code> for monitoring and alerting.</li><li>Logs are structured (<code>tracing</code>) and controllable via <code>RUST_LOG</code>.</li><li>Startup fails if database migrations fail (no partially-started service with wrong schema).</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li>UI remains responsive: networking and storage live in <code>soma-daemon</code>.</li><li>Peer loop is not blocked by slow handlers: event dispatch uses bounded queues/backpressure.</li></ul><h2 id="maintainability" tabindex="-1">Maintainability <a class="header-anchor" href="#maintainability" aria-label="Permalink to &quot;Maintainability&quot;">​</a></h2><ul><li>New features should be implemented primarily in shared crates (<code>backend/crates/*</code>) with thin controller layers in bins.</li><li>Protocol changes are expressed in <code>proto/</code> and compiled via <code>backend/crates/proto-build</code>.</li></ul>',12)])])}const b=a(l,[["render",n]]);export{m as __pageData,b as default};
